      "matter_id": "MTR-2024-00010",
      "matter_code": "ARB/BLR/0010/2024",
      "client_id": "CLI-00207",
      "title": "Research Memo \u2014 Choudhary Energy Ltd. v Redwood Cement Ltd.",
      "document_type": "Research Memo",
      "author_id": "MEM-00047",
      "author_name": "Ekapad Walia",
      "date": "2024-10-14",
      "status": "Final",
