  "clauses": [
    {
      "id": "CLS-001",
      "title": "Indemnity Cap & De Minimis Threshold",
      "category": "M&A / Corporate",
      "practice_area": "M&A",
      "market_standard": "Aggregate liability capped at 15% to 20% of Transaction Consideration for general warranties; 100% for Fundamental Warranties & Tax.",
      "standard_text": "The aggregate maximum liability of the Seller in respect of all Warranty Claims shall not exceed 15% (fifteen percent) of the Purchase Price, save and except in the case of Fundamental Warranties, Tax Claims, or Fraud, where liability shall not exceed the Purchase Price.",
      "fallback_pro_buyer": "The aggregate maximum liability of the Seller for all claims including Tax and Fundamental Warranties shall be 100% of the Purchase Price with a 36-month survival period.",
      "fallback_pro_seller": "The aggregate maximum liability of the Seller for all claims shall not exceed 10% of the Purchase Price, with an individual de minimis threshold of \u20b915,00,000 and a basket threshold of \u20b91,00,00,000.",
      "usage_count": 142,
      "success_rate": "92% agreed",
      "used_in_matters": [
        "MTR-2019-00001",
        "MTR-2021-00045",
        "MTR-2023-00112"
      ]
    },
    {
      "id": "CLS-002",
      "title": "Locked-Box Anti-Leakage & Value Protection",
      "category": "M&A / Finance",
      "practice_area": "M&A",
      "market_standard": "Strict covenant against leakage between Locked-Box Date and Completion, with rupee-for-rupee indemnity plus interest.",
      "standard_text": "The Seller covenants that between the Locked-Box Date and the Closing Date, there has not been and shall not be any Leakage from the Company to or for the benefit of the Seller or its Affiliates, save for Permitted Leakage as set forth in Schedule 4.",
      "fallback_pro_buyer": "Buyer may deduct proven leakage directly from the deferred consideration or draw upon the Escrow Account with 5 Business Days notice.",
      "fallback_pro_seller": "Seller leakage claims must be notified within 6 months of Closing, failing which all claims shall be deemed irrevocably waived.",
      "usage_count": 89,
      "success_rate": "88% agreed",
      "used_in_matters": [
        "MTR-2019-00001",
        "MTR-2022-00088"
      ]
    },
    {
      "id": "CLS-003",
      "title": "Emergency Arbitrator & SIAC Expedited Seat",
      "category": "Disputes / Arbitration",
      "practice_area": "Arbitration",
      "market_standard": "Seat in Singapore, governed by SIAC Rules (6th/7th Edition), with express right to seek Emergency Interim Relief.",
      "standard_text": "Any dispute arising out of or in connection with this Agreement shall be referred to and finally resolved by arbitration administered by the Singapore International Arbitration Centre (SIAC) in accordance with the Arbitration Rules of SIAC. The seat of the arbitration shall be Singapore. The tribunal shall consist of three arbitrators. The language of the arbitration shall be English.",
      "fallback_pro_buyer": "Sole arbitrator appointed by SIAC Chairman if claim is under ,000,000 under Expedited Procedure rules.",
      "fallback_pro_seller": "Seat in Mumbai under Indian Arbitration & Conciliation Act, 1996 with Bombay High Court supervisory jurisdiction.",
      "usage_count": 167,
      "success_rate": "95% agreed",
      "used_in_matters": [
        "MTR-2020-00015",
        "MTR-2023-00098",
        "MTR-2024-00004"
      ]
    },
    {
      "id": "CLS-004",
      "title": "Minority Shareholder Tag-Along & Pre-emption",
      "category": "Corporate / Shareholders",
      "practice_area": "Corporate",
      "market_standard": "Pro-rata tag-along right on transfers of >10% shareholding, alongside statutory Right of First Refusal (ROFR).",
      "standard_text": "If any Promoter proposes to transfer shares representing more than 10% of the Equity Share Capital to a Third Party, the Minority Shareholders shall have the right, but not the obligation, to participate in such sale on terms and conditions no less favorable.",
      "fallback_pro_buyer": "Full tag-along on any transfer by Promoters, irrespective of threshold percentage.",
      "fallback_pro_seller": "Tag-along applies only upon change of control (>50% transfer).",
      "usage_count": 114,
      "success_rate": "85% agreed",
      "used_in_matters": [
        "MTR-2021-00033",
        "MTR-2023-00145"
      ]
    },
    {
      "id": "CLS-005",
      "title": "Material Adverse Change (MAC) Exclusion",
      "category": "M&A / Banking",
      "practice_area": "M&A",
      "market_standard": "Excludes macroeconomic downturns, industry-wide tariff changes, changes in law, and armed conflict unless disproportionately impacting target.",
      "standard_text": "Material Adverse Effect shall mean any event or change that has a material adverse effect on the business, financial condition or results of operations of the Company, provided that none of the following shall be taken into account: (i) changes in general economic or capital market conditions; (ii) changes in applicable laws or accounting standards; (iii) industry-wide regulatory tariffs.",
      "fallback_pro_buyer": "Broad definition covering any event causing a reduction of EBITDA by greater than 15%.",
      "fallback_pro_seller": "Strictly confined to catastrophic damage to manufacturing facilities exceeding \u20b950 crore not covered by insurance.",
      "usage_count": 98,
      "success_rate": "81% agreed",
      "used_in_matters": [
        "MTR-2019-00001",
        "MTR-2022-00210"
      ]
    }
  ],
